const email = encodeURIComponent(msg.payload.email.trim());
const pass = encodeURIComponent(msg.payload.password);

msg.headers = { "Content-Type": "application/x-www-form-urlencoded" };
msg.payload = `username=${email}&password=${pass}`;
return msg;

if (msg.statusCode === 200 && msg.payload.access_token) {
    global.set("token", msg.payload.access_token);
    msg.payload = "✅ Zalogowano pomyślnie!";
} else {
    msg.payload = "❌ Błędny e-mail lub hasło!";
}
return msg;

const d = msg.payload;

const msgTotal = { payload: d.total_transactions };

const msgQuality = { payload: d.data_quality_score };

const vols = d.total_volume_by_currency || {};
const chartData = Object.entries(vols).map(([waluta, kwota]) => ({
    x: waluta,
    y: kwota
}));
const msgChart = { payload: chartData };

return [msgTotal, msgQuality, msgChart];

const token = global.get("token");

if (!token) {
    return [null, {
        payload: {
            pages: {
                hide: [
                    "Transakcje zaakcpetowane",
                    "Transakcje odrzucone",
                    "Panel administratora",
                    "Zarządzanie transakcjami"
                ]
            },
            groups: {
                hide: ["Wskaźniki Globalne"]
            }
        }
    }];
}

msg.headers = { "Authorization": "Bearer " + token };
return [msg, null];

if (msg.statusCode === 200 && msg.payload.status === "ok") {
    msg.payload = "🟢 Online (" + msg.payload.message + ")";
} else {
    msg.payload = "🔴 Offline (błąd połączenia)";
}
return msg;

const u = msg.payload;
const rolaPL = u.role === "admin" ? "Administrator" : "Klient";
const zrodlo = u.source_id ? ("Źródło ID: " + u.source_id) : "Wszystkie źródła";

msg.payload = `${u.email} | Rola: ${rolaPL} | ${zrodlo}`;
return msg;

global.set("token", null);

return [
    { payload: "🔒 Wylogowano z systemu" },
    { payload: "Brak (niezalogowany)" },
    {
        payload: {
            pages: {
                hide: [
                    "Transakcje zaakcpetowane",
                    "Transakcje odrzucone",
                    "Panel administratora",
                    "Zarządzanie transakcjami"
                ]
            },
            groups: {
                hide: ["Wskaźniki Globalne"]
            }
        }
    }
];

const stronyKlienta = ["Transakcje zaakcpetowane", "Transakcje odrzucone"];
const stronyAdmina = ["Panel administratora", "Zarządzanie transakcjami"];

if (msg.statusCode === 200 && msg.payload.role === "admin") {
    msg.payload = {
        pages: { show: [...stronyKlienta, ...stronyAdmina] },
        groups: { show: ["Wskaźniki Globalne"] }
    };
} else if (msg.statusCode === 200) {
    msg.payload = {
        pages: { show: stronyKlienta, hide: stronyAdmina },
        groups: { show: ["Wskaźniki Globalne"] }
    };
} else {
    msg.payload = {
        pages: { hide: [...stronyKlienta, ...stronyAdmina] },
        groups: { hide: ["Wskaźniki Globalne"] }
    };
}
return msg;

