}));

return msg;

const token = global.get("token");
msg.headers = {
    "Authorization": "Bearer " + token,
    "Content-Type": "application/json"
};
msg.payload = {
    email: msg.payload.email,
    password: msg.payload.password,
    role: msg.payload.role,
    source_id: msg.payload.role === "admin" ? null : Number(msg.payload.source_id)
};
return msg;

if (msg.statusCode === 201) {
    msg.payload = `Utworzono konto: ${msg.payload.email} (ID: ${msg.payload.id})`;
} else {
    msg.payload = `Błąd: ${msg.payload.detail || msg.statusCode}`;
}
return msg;

const token = global.get("token");
if (!token) return null;
msg.headers = { "Authorization": "Bearer " + token };
msg.payload = {};
return msg;

const token = global.get("token");
const p = msg.payload;
msg.headers = {
    "Authorization": "Bearer " + token,
    "Content-Type": "application/json"
};
msg.payload = {
    source_id: Number(p.source_id),
    transactions: [{
        external_ref: p.external_ref,
        amount: Number(p.amount),
        currency: p.currency,
        timestamp: p.timestamp,
        status: p.status
    }]
};
return msg;

if (msg.statusCode === 201) {
    msg.payload = `✅ Wysłano transakcję! (Przyjęto rekordów: ${msg.payload.processed_count}) — uruchom ETL, aby ją przetworzyć.`;
} else {
    msg.payload = `❌ Błąd wysyłania: ${msg.payload.detail || msg.statusCode}`;
}
return msg;

const r = msg.payload;
msg.payload = `Zakończono! Nowe czyste transakcje: ${r.clean_count} | Wykryte błędy: ${r.error_count}`;
return msg;

msg.payload = msg.payload.map(u => ({
    "ID": u.id,
    "E-mail": u.email,
    "Rola": u.role === "admin" ? "Administrator" : "Klient",
    "ID Źródła": u.source_id ? u.source_id : "Wszystkie (Admin)",
    "Aktywny": u.active ? "Tak" : "Nie",
    "Utworzono": u.created_at.replace("T", " ").slice(0, 19)
}));

return msg;

if (msg.statusCode === 201) {
    msg.payload = `Dodano firme: ${msg.payload.name} (Wersja: ${msg.payload.schema_version})`;
} else {
    msg.payload = `Błąd: ${msg.payload.detail || msg.statusCode}`;
}
